// Functions receive shared services and state through an explicit application context.
export function install(ctx){
async function usersPage(){if(!ctx.profile?.is_owner&&ctx.profile?.role!=='admin'){ctx.render('home');return}ctx.shell(`${ctx.head('Gerenciar usuários','Aprove solicitações e defina os papéis de acesso.')}<div class="note">Administradores gerenciam acessos. A equipe aprovada trabalha na base compartilhada da Avelon. Defina por usuário quais módulos e operações ele pode acessar.</div><section class="panel" style="margin-top:22px" id="user-list"><p class="loading">Carregando usuários…</p></section>`);try{const users=await ctx.api('/rest/v1/rpc/admin_users_v3',{method:'POST',body:{}});ctx.$('#user-list').innerHTML=`<div class="table-wrap"><table><thead><tr><th>Usuário / e-mail</th><th>Papel</th><th>Acesso</th><th></th></tr></thead><tbody>${users.map(u=>`<tr><td><strong>${ctx.esc(u.username||'Sem nome')}</strong><br><span class="muted">${ctx.esc(u.email)}</span></td><td><select aria-label="Papel de ${ctx.esc(u.username||u.email)}" id="role-${u.id}" ${(u.id===ctx.profile.id||u.is_owner)?'disabled':''}><option value="member" ${u.role==='member'?'selected':''}>Usuário</option><option value="admin" ${u.role==='admin'?'selected':''}>${u.is_owner?'Mestre Criador':'Administrador'}</option></select></td><td><select aria-label="Acesso de ${ctx.esc(u.username||u.email)}" id="active-${u.id}" ${(u.id===ctx.profile.id||u.is_owner)?'disabled':''}><option value="true" ${u.active?'selected':''}>Liberado</option><option value="false" ${!u.active?'selected':''}>Aguardando / bloqueado</option></select></td><td>${(u.id===ctx.profile.id||u.is_owner)?'<span class="badge">Acesso protegido</span>':`<button class="secondary small" data-user="${u.id}">Salvar acesso</button> <button class="secondary small" data-permissions="${u.id}">Permissões</button>`}${ctx.profile.is_owner?` <button class="secondary small" data-session-user="${u.id}">Login e inatividade</button>`:''}</td></tr>`).join('')}</tbody></table></div>`;document.querySelectorAll('[data-session-user]').forEach(b=>b.onclick=()=>sessionPolicyDialog(users.find(u=>u.id===b.dataset.sessionUser)));document.querySelectorAll('[data-permissions]').forEach(b=>b.onclick=()=>ctx.permissionEditor(b.dataset.permissions));document.querySelectorAll('[data-user]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await ctx.api('/rest/v1/rpc/admin_update_user',{method:'POST',body:{p_user:b.dataset.user,p_role:ctx.$('#role-'+b.dataset.user).value,p_active:ctx.$('#active-'+b.dataset.user).value==='true'}});ctx.toast('Permissões atualizadas.')}catch(e){ctx.toast(e.message)}finally{b.disabled=false}})}catch(e){ctx.$('#user-list').textContent=e.message}}
function sessionPolicyDialog(user){
 const minutes=Number(user.session_idle_minutes||30),factor=minutes%1440===0?1440:minutes%60===0?60:1;
 const d=ctx.modal('Login e inatividade · '+ctx.esc(user.username||user.email),`<form id="session-policy-form"><label class="field">Ao fechar o sistema<select name="persistent"><option value="true" ${user.session_persistent?'selected':''}>Manter conectado neste aparelho</option><option value="false" ${!user.session_persistent?'selected':''}>Pedir login ao fechar a aba ou navegador</option></select></label><div class="grid2">${ctx.field('Desconectar após ficar sem uso','idle_value','number',minutes/factor,'required min="1" step="1"')}<label class="field">Unidade<select name="idle_unit"><option value="1" ${factor===1?'selected':''}>Minutos</option><option value="60" ${factor===60?'selected':''}>Horas</option><option value="1440" ${factor===1440?'selected':''}>Dias</option></select></label></div><p class="note">Prazo máximo: dez dias sem atividade. Atualizações automáticas não contam como uso. O botão Sair encerra o acesso; bloqueios administrativos continuam valendo. Evite manter conectado em aparelhos compartilhados.</p><p id="session-policy-error" role="alert"></p><div class="form-actions"><button type="button" class="secondary" data-close>Cancelar</button><button class="primary" type="submit">Salvar regra de login</button></div></form>`);
 d.querySelector('form').onsubmit=async e=>{e.preventDefault();const form=new FormData(e.target),idle=Number(form.get('idle_value'))*Number(form.get('idle_unit')),persistent=form.get('persistent')==='true';e.submitter.disabled=true;try{if(!Number.isInteger(idle)||idle<1||idle>14400)throw Error('Escolha um prazo entre um minuto e dez dias.');await ctx.rpc('admin_set_session_policy',{p_user:user.id,p_persistent:persistent,p_idle_minutes:idle});if(user.id===ctx.profile.id){Object.assign(ctx.profile,{session_persistent:persistent,session_idle_minutes:idle});ctx.applySessionPolicy(ctx.profile)}d.close();usersPage();ctx.toast('Regra de login salva para este usuário.')}catch(err){d.querySelector('#session-policy-error').textContent=err.message;e.submitter.disabled=false}};
}
Object.assign(ctx,{usersPage});
}
